    """Job entry point (design plan section 5.1, T1). Parameters: none."""
    logging.basicConfig(
        level=logging.INFO, format="%(asctime)s %(levelname)s %(name)s %(message)s"
    )

    get_probability = F.udf(lambda v: float(v[1]), FloatType())

    # spark = (SparkSession
